    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void finish() {
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }

    static final String BODY = String.join("\n",
            "int total = 0;",
            "String name = \"bob\";",
            "double unusedRate = 0.5;",
            "for (int i = 0; i < 3; i++) {",
            "    total = total + i;",
            "}",
            "boolean done;",
            "System.out.println(name + total);");

    public static void main(String[] args) {
        check("declaredLocals in declaration order", "[total, name, unusedRate, done]",
                String.valueOf(UnusedLocalFinder.declaredLocals(BODY)));
        check("unusedLocals sorted", "[done, unusedRate]",
                String.valueOf(UnusedLocalFinder.unusedLocals(BODY)));
        check("a loop counter is not a declaration here", "[]",
                String.valueOf(UnusedLocalFinder.declaredLocals("for (int i = 0; i < 3; i++) { }")));
        check("a type that only looks right is skipped", "[]",
                String.valueOf(UnusedLocalFinder.declaredLocals("Stringy s = null;")));
        check("a longer name does not count as a use", "[sum]",
                String.valueOf(UnusedLocalFinder.unusedLocals("int sum = 0;\nreturn sums;")));
        check("a use on a later line counts", "[]",
                String.valueOf(UnusedLocalFinder.unusedLocals("int sum = 0;\nreturn sum;")));
        check("a name used only in its own declaration is unused", "[k]",
                String.valueOf(UnusedLocalFinder.unusedLocals("long k = k;")));
        check("an empty body", "[]", String.valueOf(UnusedLocalFinder.declaredLocals("")));
        finish();
    }
}

