public class UnusedLocalFinder {

    private static final java.util.List<String> TYPES = java.util.List.of(
            "int", "long", "double", "boolean", "char", "String");

    public static java.util.List<String> declaredLocals(String body) {
        java.util.List<String> names = new java.util.ArrayList<>();
        for (String line : body.split("\n", -1)) {
            String name = declaredName(line.trim());
            if (name != null && !names.contains(name)) {
                names.add(name);
            }
        }
        return names;
    }

    public static java.util.List<String> unusedLocals(String body) {
        String[] lines = body.split("\n", -1);
        java.util.List<String> unused = new java.util.ArrayList<>();
        for (String name : declaredLocals(body)) {
            boolean used = false;
            for (String line : lines) {
                String text = line.trim();
                if (name.equals(declaredName(text))) {
                    continue;
                }
                if (containsIdentifier(text, name)) {
                    used = true;
                    break;
                }
            }
            if (!used) {
                unused.add(name);
            }
        }
        java.util.Collections.sort(unused);
        return unused;
    }

    private static String declaredName(String text) {
        for (String type : TYPES) {
            if (!text.startsWith(type + " ")) {
                continue;
            }
            String rest = text.substring(type.length()).trim();
            int i = 0;
            while (i < rest.length() && isIdentifierPart(rest.charAt(i))) {
                i++;
            }
            if (i == 0) {
                return null;
            }
            String name = rest.substring(0, i);
            while (i < rest.length() && rest.charAt(i) == ' ') {
                i++;
            }
            if (i < rest.length() && (rest.charAt(i) == '=' || rest.charAt(i) == ';')) {
                return name;
            }
            return null;
        }
        return null;
    }

    private static boolean containsIdentifier(String text, String name) {
        int i = text.indexOf(name);
        while (i >= 0) {
            boolean beforeOk = i == 0 || !isIdentifierPart(text.charAt(i - 1));
            int after = i + name.length();
            boolean afterOk = after >= text.length() || !isIdentifierPart(text.charAt(after));
            if (beforeOk && afterOk) {
                return true;
            }
            i = text.indexOf(name, i + 1);
        }
        return false;
    }

    private static boolean isIdentifierPart(char c) {
        return Character.isLetterOrDigit(c) || c == '_' || c == '$';
    }
}
